sksl:
uniform shader image;
uniform float2 size;
uniform float time;
layout(color) uniform half4 filterColor;
uniform float density;
uniform float preserve;
uniform float saturation;
uniform float opacity;
float4 tex(float2 p) {
    return float4(image.eval(clamp(p, float2(0.0), size)));
}
float3 unp(float4 c) {
    return c.rgb / max(c.a, 0.0001);
}
float luma(float3 c) {
    return dot(c, float3(0.2126, 0.7152, 0.0722));
}
half4 fin(float4 o, float4 r, float op) {
    return half4(mix(o, r, saturate(op)));
}
float3 sat3(float3 c, float s) {
    return mix(float3(dot(c, float3(0.2126, 0.7152, 0.0722))), c, s);
}
half4 main(float2 coord) {
    float4 c = tex(coord);
    float3 s = unp(c);
    float3 o = mix(s, s * float3(filterColor.rgb) * 2.0, density);
    if (preserve > 0.5) o *= luma(s) / max(luma(o), 0.0001);
    o = sat3(o, saturation);
    return fin(c, float4(saturate(o) * c.a, c.a), opacity);
}
